                                    // X swaps α and β
                                    let mut new_fields = std::collections::HashMap::new();
                                    new_fields
                                        .insert("_alpha_real".to_string(), Value::Float(beta_real));
                                    new_fields
                                        .insert("_alpha_imag".to_string(), Value::Float(beta_imag));
                                    new_fields
